#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""fd2sav_level.py — FD2.SAV 存档角色批量升级工具（真实升级模拟）

按原版 FD2.EXE 的升级机制逐级模拟：每级 5 次成长掷点
（gain = lo + rand()%(hi-lo)，非零则累加，stat_growth_roll@0x1E529）、
法术按习得表等级补全（spell_learn_add@0x1D79C）、装备派生重算
（ent_stats_apply_equipment@0x1145A）、经验清零、HP/MP 回满。
容器层完成 XOR 流解码与校验和重算（save_transform@0x4DF28 /
save_sum@0x4DF09）。机制细节与字段证据见 fd2re/docs/fd2sav-editing.md。

用法示例：
  python fd2sav_level.py                          # 默认：遍历已有角色 → 未转职 40 级
  python fd2sav_level.py --all                    # 补全全部 32 人并升到 40 级
  python fd2sav_level.py --ids 0,9 --level 30     # 指定角色/等级
  python fd2sav_level.py --from-template --all    # 全员按模板重建后从底级升满（幂等）
  python fd2sav_level.py --dry-run                # 只看计划不落盘
  python fd2sav_level.py --verify                 # 只读校验并列出 roster

随机掷点无法复现游戏内 RNG 序列（运行时状态），但公式与取值范围
与原版逐指令一致；--seed N 可让脚本自身可复现。
"""
import argparse
import random
import shutil
import struct
import sys
import time

SAVE_SIZE = 22987            # 0x59CB
CTX_OFF = 0                  # +0..2210   战场 ctx
ROSTER_OFF = 2211            # +2211..4770 roster 32x80
ENT_OFF = 4771               # +4771..    战场实体表 96x80（前 ent_count 条有效）
SPAWNER_OFF = 12451          # +12451..12482
AUX_OFF = 12483              # +12483 g_turn_count
COUNT_OFF = 12484            # +12484 g_ent_count
STATE_OFF = 12485            # +12485 进度字节 g_state（0xFF=无进度）
ROSTER_COUNT_OFF = 12492     # +12492 g_roster_count
SLOT_BASE, SLOT_STRIDE, SLOT_COUNT = 12587, 2600, 4
CKSUM_OFF = 22983            # +22983 u32 LE 校验和
REC = 80                     # roster/ent 记录长
ROSTER_MAX = 32

# ---- 数据表（程序化提取自 fd2re/src/tables.c，原始出处 FD2.EXE dseg03）----
# templates: 0x61DA1 24B/条 —— [0]AI子型(+31) [1]职业系(+32) [2]等级(+33)
#   [3..4]HP基 [5..6]MP基 [7]移动力(+59) [8..11]法术位图(+26..29)
#   [12]/[13]道具槽0/1 id [14..17]道具槽2..5 id(0xFF=空)
#   [18..19]ATK基(+55) [20..21]DEF基(+57) [22..23]HIT/EVA基(+62)
# growth: 0x620A1 11B/条 —— 五对 [lo,hi] 对应 +55/+57/+62/+66/+70，
#   字节[10]=法术习得组（0xFF=无）
# learn: 0x626B3 6x12B —— 每组 6 对 (习得等级, 法术id)，255 终止
# weapon: 0x602AD 23B/条 —— [1..2]ATK [3..4]HIT [5..6]DEF [7..8]EVA（i16 加成）
T_HEX = {"templates": "", "growth": "", "weapon": "", "learn": "051109010f1a15021a1bffff07140b0e101218161e17ffff121318151e19ffffffffffff140a1806ffffffffffffffff0418ffffffffffffffffffff021effffffffffffffffffff"}

TEMPLATES = bytes.fromhex(T_HEX["templates"])
GROWTH = bytes.fromhex(T_HEX["growth"])
LEARN = bytes.fromhex(T_HEX["learn"])
WEAPON = bytes.fromhex(T_HEX["weapon"])

u16 = lambda b, o: b[o] | (b[o + 1] << 8)
i16 = lambda b, o: struct.unpack_from("<h", b, o)[0]


def put16(r, o, v):
    r[o] = v & 0xFF
    r[o + 1] = (v >> 8) & 0xFF


# ---------------- 容器编解码（0x4DF28 / 0x4DF09） ----------------

def rol16(v, c):
    return ((v << c) | (v >> (16 - c))) & 0xFFFF


def decode(raw):
    key = 165
    out = bytearray(len(raw))
    for i, b in enumerate(raw):
        key = rol16((key - 28652) & 0xFFFF, 3)
        out[i] = b ^ (key & 0xFF)
    return out


encode = decode  # 对称 XOR 流


def checksum_ok(rec):
    return sum(rec[:CKSUM_OFF]) == struct.unpack_from("<I", rec, CKSUM_OFF)[0]


def finalize(rec):
    """重算校验和并编码为落盘格式"""
    struct.pack_into("<I", rec, CKSUM_OFF, sum(rec[:CKSUM_OFF]))
    return encode(bytes(rec))


# ---------------- 表访问 ----------------

def tmpl(cid):
    return TEMPLATES[cid * 24:cid * 24 + 24]


def growth_row(cid):
    return GROWTH[cid * 11:cid * 11 + 11]


def learn_pairs(group):
    if group == 0xFF or group >= 6:
        return []
    out = []
    for j in range(6):
        lvl, sid = LEARN[group * 12 + 2 * j], LEARN[group * 12 + 2 * j + 1]
        if lvl != 255:
            out.append((lvl, sid))
    return out


def weapon_of(item):
    w = WEAPON[item * 23:item * 23 + 23]
    return w if len(w) == 23 else None


# ---------------- 实体记录原语 ----------------

def equip_bonus(items):
    """+10..25 道具槽 -> (ATK,DEF,HIT,EVA) 加成（数量字节 bit6=已装备）"""
    atk = dfn = hit = eva = 0
    for i in range(8):
        if not (items[2 * i] & 0x40):
            continue
        w = weapon_of(items[2 * i + 1])
        if w:
            atk += i16(w, 1); hit += i16(w, 3)
            dfn += i16(w, 5); eva += i16(w, 7)
    return atk, dfn, hit, eva


def apply_derived(r):
    atk, dfn, hit, eva = equip_bonus(bytes(r[10:26]))
    put16(r, 72, u16(r, 55) + atk)
    put16(r, 74, u16(r, 57) + dfn)
    put16(r, 76, u16(r, 62) + hit)
    put16(r, 78, u16(r, 62) + eva)


def spell_bits(cid, level):
    """习得等级 <= level 的法术位集"""
    bits = 0
    for lvl, sid in learn_pairs(growth_row(cid)[10]):
        if lvl <= level and sid < 48:
            bits |= 1 << sid
    return bits


def or_spells(r, bits):
    # 位图 +26..31（法术 id<=31 实际只落在 +26..29；+30/+31 为他义，置位无害省略）
    for k in range(4):
        r[26 + k] |= (bits >> (8 * k)) & 0xFF


def spawn_at(cid, level):
    """roster_spawn_ent@0x112A5 公式（等级可指定）"""
    d, g = tmpl(cid), growth_row(cid)
    r = bytearray(REC)
    r[5] = 0; r[6] = 2; r[7] = cid; r[8] = cid; r[9] = 0
    r[10] = 0x40; r[11] = d[12]; r[12] = 0x40; r[13] = d[13]
    for i in range(4):
        if d[14 + i] == 255:
            r[14 + 2 * i] = 0x80; r[15 + 2 * i] = 0xFF
        else:
            r[14 + 2 * i] = 0; r[15 + 2 * i] = d[14 + i]
    r[22] = 0x80; r[24] = 0x80
    r[26], r[27], r[28], r[29] = d[8], d[9], d[10], d[11]
    r[30] = 0; r[31] = d[0]; r[32] = d[1]; r[33] = level
    r[49] = 0xFF; r[59] = d[7]; r[60] = 0
    put16(r, 55, level * g[0] + u16(d, 18))
    put16(r, 57, level * g[2] + u16(d, 20))
    put16(r, 62, level * g[4] + u16(d, 22))
    hp = u16(d, 3) + (level - 1) * g[6]
    mp = u16(d, 5) + (level - 1) * g[8]
    put16(r, 64, hp); put16(r, 66, hp)
    put16(r, 68, mp); put16(r, 70, mp)
    or_spells(r, spell_bits(cid, level))
    apply_derived(r)
    return r


def levelup_roll(rng, lo, hi):
    """stat_growth_roll@0x1E529: gain = lo + rand()%(hi-lo)；hi==lo 则 gain=lo"""
    if hi < lo:
        hi = lo
    gain = lo
    if hi > lo:
        gain += rng.randrange(hi - lo)
    return gain


def simulate_levels(r, cid, from_lv, to_lv, rng):
    """逐级掷点（真实升级路径），返回五维增量"""
    g = growth_row(cid)
    gains = {55: 0, 57: 0, 62: 0, 66: 0, 70: 0}
    for _lv in range(from_lv + 1, to_lv + 1):
        for off, pi in ((55, 0), (57, 2), (62, 4), (66, 6), (70, 8)):
            gain = levelup_roll(rng, g[pi], g[pi + 1])
            if gain:
                gains[off] += gain
                put16(r, off, u16(r, off) + gain)
    return gains


def demote(r, cid):
    """转职回退：职业/职业系/移动力恢复模板值（已学法术保留）"""
    d = tmpl(cid)
    r[7] = cid
    r[32] = d[1]
    r[59] = d[7]


def finalize_entry(r, cid, target, old_spells=0):
    """等级/经验/法术/满血/派生 一致化收尾"""
    demote(r, cid)
    r[33] = target
    r[60] = 0; r[61] = 0
    or_spells(r, spell_bits(cid, target) | old_spells)
    put16(r, 64, u16(r, 66))  # HP=MaxHP
    put16(r, 68, u16(r, 70))  # MP=MaxMP
    apply_derived(r)


def entry_spells(r):
    return r[26] | r[27] << 8 | r[28] << 16 | r[29] << 24


# ---------------- 存档级操作 ----------------

def load_save(path):
    raw = open(path, "rb").read()
    if len(raw) != SAVE_SIZE:
        sys.exit("错误：文件长度 %d != %d，不是有效 FD2.SAV" % (len(raw), SAVE_SIZE))
    rec = decode(raw)
    return rec, checksum_ok(rec)


def backup(path):
    stamp = time.strftime("%Y%m%d-%H%M%S")
    bak = "%s.bak-%s" % (path, stamp)
    shutil.copy2(path, bak)
    return bak


def main():
    ap = argparse.ArgumentParser(
        description="FD2.SAV 角色批量升级（真实升级模拟，默认：已有角色 → 未转职 40 级）")
    ap.add_argument("--save", default="FD2.SAV", help="存档路径（默认 ./FD2.SAV）")
    ap.add_argument("--level", type=int, default=40, help="目标等级（默认 40）")
    scope = ap.add_mutually_exclusive_group()
    scope.add_argument("--ids", help="只处理这些角色 id（逗号分隔，如 0,9,30）")
    scope.add_argument("--all", action="store_true",
                       help="补全全部 32 名角色（缺员按模板入队后升级）")
    ap.add_argument("--from-template", action="store_true",
                    help="先按模板重建条目再升级（保留物品栏与已学法术；幂等）")
    ap.add_argument("--template-items", action="store_true",
                    help="配合 --from-template：物品栏也用模板初始装备（默认保留原物品）")
    ap.add_argument("--no-slots", action="store_true", help="不更新 4 个章节槽")
    ap.add_argument("--seed", type=int, default=None, help="随机种子（可复现）")
    ap.add_argument("--dry-run", action="store_true", help="只显示计划，不写盘")
    ap.add_argument("--no-backup", action="store_true", help="不写备份")
    ap.add_argument("--verify", action="store_true", help="只读：校验并列出 roster")
    args = ap.parse_args()

    if not (1 <= args.level <= 99):
        sys.exit("错误：目标等级须在 1..99")
    if args.template_items and not args.from_template:
        sys.exit("错误：--template-items 需配合 --from-template")

    rec, ok = load_save(args.save)
    print("读档 %s：长度 %d，校验和 %s，进度字节=%s，roster_count=%d" % (
        args.save, len(rec), "OK" if ok else "FAIL",
        hex(rec[STATE_OFF]), rec[ROSTER_COUNT_OFF]))
    if not ok and not args.verify:
        sys.exit("错误：校验和不通过，拒绝修改")
    if args.verify:
        for i in range(rec[ROSTER_COUNT_OFF]):
            b = ROSTER_OFF + i * REC
            e = rec[b:b + REC]
            print("  slot%2d id=%2d cls=%2d lv=%2d HP=%d/%d MP=%d/%d exp=%d "
                  "ATK/DEF/HIT/EVA=%d/%d/%d/%d" % (
                      i, e[8], e[7], e[33], u16(e, 64), u16(e, 66),
                      u16(e, 68), u16(e, 70), e[60],
                      u16(e, 72), u16(e, 74), u16(e, 76), u16(e, 78)))
        return

    rng = random.Random(args.seed)

    # ---- 圈定角色（默认=遍历已有 roster）----
    roster = [rec[ROSTER_OFF + i * REC:ROSTER_OFF + (i + 1) * REC]
              for i in range(rec[ROSTER_COUNT_OFF])]
    existing = {e[8]: i for i, e in enumerate(roster)}
    recruits = []
    if args.ids:
        want = [int(x) for x in args.ids.split(",")]
        for cid in want:
            if cid not in existing:
                sys.exit("错误：角色 id %d 不在 roster 中（现有：%s）"
                         % (cid, sorted(existing)))
        selected = set(want)
    elif args.all:
        selected = set(existing)
        recruits = [cid for cid in range(32) if cid not in existing]
    else:
        selected = set(existing)

    # ---- 逐角色处理（真实升级）----
    new_roster = []
    report = []
    for e in roster:
        cid = e[8]
        r = bytearray(e)
        if cid in selected:
            promoted = r[7] >= 50
            cur_lv = r[33]
            old_spells = entry_spells(r)
            if args.from_template:
                base_lv = tmpl(cid)[2]
                fresh = spawn_at(cid, base_lv)
                if not args.template_items:
                    fresh[10:26] = r[10:26]          # 保留物品栏
                or_spells(fresh, old_spells)          # 保留已学法术
                r = bytearray(fresh)
                cur_lv = base_lv
            start_lv = cur_lv
            gains = simulate_levels(r, cid, min(cur_lv, args.level),
                                    args.level, rng)
            finalize_entry(r, cid, args.level, old_spells)
            report.append((cid, start_lv, promoted, gains, bytes(r)))
        else:
            report.append((cid, r[33], False, None, bytes(r)))
        new_roster.append(bytes(r))

    # --all 补员：模板底级入队再升满
    for cid in recruits:
        base_lv = tmpl(cid)[2]
        r = spawn_at(cid, base_lv)
        gains = simulate_levels(r, cid, base_lv, args.level, rng)
        finalize_entry(r, cid, args.level)
        new_roster.append(bytes(r))
        report.append((cid, base_lv, False, gains, bytes(r)))

    count = len(new_roster)
    if count > ROSTER_MAX:
        sys.exit("错误：roster 溢出（%d > 32）" % count)

    print("\nid  旧lv (转职) -> 新lv   +ATK +DEF +HIT  +MHP +MMP  法术  新ATK/DEF/HIT/EVA")
    for cid, old_lv, promoted, gains, e in report:
        if gains is None:
            print("%2d   %2d        ->  不变（未圈定）" % (cid, old_lv))
            continue
        tag = "(已转)" if promoted else "      "
        ns = bin(entry_spells(e)).count("1")
        print("%2d  %2d %s -> %2d    %4d %4d %4d  %4d %4d   %2d    %d/%d/%d/%d" % (
            cid, old_lv, tag, e[33],
            gains[55], gains[57], gains[62], gains[66], gains[70], ns,
            u16(e, 72), u16(e, 74), u16(e, 76), u16(e, 78)))

    if args.dry_run:
        print("\n[dry-run] 未写盘。")
        return

    # ---- 写主 roster（不足 32 条以 0 填充）----
    rec[ROSTER_OFF:ROSTER_OFF + ROSTER_MAX * REC] = \
        b"".join(new_roster) + b"\x00" * ((ROSTER_MAX - count) * REC)
    rec[ROSTER_COUNT_OFF] = count

    # ---- 战场实体表：同名我方单位同步（防 battle_sync_to_roster 回写降级）----
    n_patched = 0
    for i in range(rec[COUNT_OFF]):
        off = ENT_OFF + i * REC
        e = rec[off:off + REC]
        if e[6] == 2 and e[8] in selected and e[8] < 32:
            r = bytearray(e)
            old_spells = entry_spells(r)
            simulate_levels(r, e[8], min(r[33], args.level), args.level, rng)
            finalize_entry(r, e[8], args.level, old_spells)
            rec[off:off + REC] = r
            n_patched += 1

    # ---- 章节槽 ----
    n_slots = 0
    if not args.no_slots:
        blob = b"".join(new_roster)
        for s in range(SLOT_COUNT):
            base = SLOT_BASE + s * SLOT_STRIDE
            if rec[base + 2560] == 0xFF:
                continue  # 空槽不动
            rec[base:base + 2560] = blob
            rec[base + 2561] = count
            n_slots += 1

    out = finalize(rec)
    bak = None if args.no_backup else backup(args.save)
    with open(args.save, "wb") as f:
        f.write(out)
    print("\n写盘：%s（%d B）roster=%d，战场我方同步 %d 条，章节槽 %d 个%s" % (
        args.save, len(out), count, n_patched, n_slots,
        "，备份 %s" % bak if bak else ""))


if __name__ == "__main__":
    main()
